<script>
document.addEventListener('DOMContentLoaded',()=>{const root=document.querySelector('[data-period-stats]'),stats=root?JSON.parse(root.dataset.periodStats):null,buttons=document.querySelectorAll('[data-period]'),targets={revenue:document.querySelector('[data-stat="revenue"]'),appointments:document.querySelector('[data-stat="appointments"]'),confirmed:document.querySelector('[data-stat="confirmed"]')},locale=@json($locale),money=v=>new Intl.NumberFormat(locale==='ar'?'ar-MA':locale==='en'?'en-US':'fr-FR').format(v)+' MAD';buttons.forEach(button=>button.addEventListener('click',()=>{if(!stats)return;buttons.forEach(item=>item.classList.toggle('is-active',item===button));const item=stats[button.dataset.period];targets.revenue.textContent=money(item.revenue);targets.appointments.textContent=item.appointments;targets.confirmed.textContent=(item.appointments?Math.round(item.confirmed/item.appointments*100):0)+'%'}));const chart=document.querySelector('[data-revenue-chart]');if(chart){const values=JSON.parse(chart.dataset.values).map(Number),max=Math.max(...values,1),points=values.map((v,i)=>`${i*(600/Math.max(values.length-1,1))},${132-v/max*102}`);chart.querySelector('.admin-chart-line').setAttribute('d','M '+points.join(' L '));chart.querySelector('.admin-chart-area').setAttribute('d','M '+points[0]+' L '+points.slice(1).join(' L ')+' L 600,150 L 0,150 Z');chart.querySelector('.admin-chart-points').innerHTML=points.map(p=>{const[x,y]=p.split(',');return `<circle class="admin-chart-point" cx="${x}" cy="${y}" r="4"/>`}).join('')}});
</script>
